// The Memory tab is the chatbot's conversation buffer: Phone | Name | History.
// A new row is appended on every message, so History grows for the same phone number
// over several rows — including across separate enquiries made days apart. We collapse
// that down to ONE row per phone number and combine every product they've ever asked
// about into a single Product Interest list, so repeat enquiries from the same
// customer stay together instead of being split or overwritten.

const rows = $input.all().map(item => item.json);

const CALLING_CODES = [
  ['971','United Arab Emirates'], ['966','Saudi Arabia'], ['968','Oman'],
  ['973','Bahrain'], ['974','Qatar'], ['965','Kuwait'], ['962','Jordan'],
  ['961','Lebanon'], ['92','Pakistan'], ['91','India'], ['880','Bangladesh'],
  ['94','Sri Lanka'], ['20','Egypt'], ['234','Nigeria'], ['254','Kenya'],
  ['27','South Africa'], ['1','United States / Canada'], ['44','United Kingdom'],
  ['86','China'], ['852','Hong Kong'], ['65','Singapore'], ['55','Brazil'],
  ['52','Mexico'], ['62','Indonesia'], ['60','Malaysia'], ['63','Philippines'],
  ['84','Vietnam'], ['98','Iran'], ['90','Turkey'], ['61','Australia'],
  ['64','New Zealand'], ['81','Japan'], ['82','South Korea'], ['49','Germany'],
  ['33','France'], ['39','Italy'], ['34','Spain'], ['31','Netherlands'], ['7','Russia / Kazakhstan']
].sort((a, b) => b[0].length - a[0].length);

function countryFromPhone(phone) {
  const digits = (phone || '').replace(/\D/g, '');
  const hit = CALLING_CODES.find(([code]) => digits.startsWith(code));
  return hit ? hit[1] : '';
}

// Collect every distinct product the bot confirmed (or, failing that, every distinct
// thing the customer asked about) across the WHOLE history — not just the first one —
// so a customer who enquired about two different products sees both, together.
function productInterestsFromHistory(history) {
  if (!history) return [];
  const found = [];
  const seen = new Set();
  const addMatch = (raw) => {
    const val = raw.trim();
    const key = val.toLowerCase();
    if (val && !seen.has(key)) { seen.add(key); found.push(val); }
  };
  const patterns = [
    /we have the ([^\n.!]+?) in stock/gi,
    /we have (?:several|some|many|a few) ([^\n.!]+?) (?:items?|units?) in stock/gi
  ];
  for (const re of patterns) {
    let m;
    while ((m = re.exec(history)) !== null) addMatch(m[1]);
  }
  if (!found.length) {
    history.split('\n').map(l => l.trim()).filter(l => /^customer:/i.test(l))
      .forEach(l => addMatch(l.replace(/^customer:\s*/i, '')));
  }
  return found;
}

// Merge every row for a phone number into one running history (rows can arrive out of
// sheet order), then dedupe on the longest/most complete snapshot for safety.
const byPhone = {};
for (const r of rows) {
  const phone = String(r.Phone || r.phone || '').trim();
  if (!phone) continue;
  const history = String(r.History || r.history || '');
  const existing = byPhone[phone];
  if (!existing) {
    byPhone[phone] = { phone, name: r.Name || r.name || '', history };
  } else {
    if (history.length > existing.history.length) existing.history = history;
    if (!existing.name && (r.Name || r.name)) existing.name = r.Name || r.name;
  }
}

const enquiries = Object.values(byPhone).map(e => {
  const products = productInterestsFromHistory(e.history);
  return {
    name: e.name || 'Unknown',
    productInterest: products.length ? products.join(', ') : '—',
    country: countryFromPhone(e.phone) || '—',
    phone: e.phone.startsWith('+') ? e.phone : '+' + e.phone
  };
});

return [{ json: { enquiries } }];
